			return err
		}
		raw = append(raw, '\n')
		warnings = append(warnings, header.Warnings...)
	} else {
		if strings.TrimSpace(indexOpts.semBinary) == "" {
			return errors.New("--sem-binary must not be empty")
		}
		var doctorWarnings []semanticWarning
